'use strict';
const gosPanel=document.getElementById('collector-state').closest('section');
for(const [panel,source,caption]of [[gosPanel,'Goszakup','Участники закупок · Бизнес'],[producerPanel,'e-ondiris','Производители · Бизнес → Производители']]){panel.classList.add('source-card');panel.querySelector('h2').textContent=source;const p=document.createElement('p');p.className='source-caption';p.textContent=caption;panel.querySelector('.section-title').after(p);const actions=panel.querySelector('.actions');actions.classList.add('source-actions');}
gosPanel.append(document.getElementById('collector-counts'));document.getElementById('collector-counts').classList.add('source-metrics');
for(const id of ['collector-start','producer-start'])document.getElementById(id).classList.add('source-action-primary');
document.getElementById('collector-pause').textContent='Пауза';
const journalPage=document.createElement('main');journalPage.hidden=true;journalPage.innerHTML='<div class="breadcrumb">Рабочее пространство / Журнал</div><div class="heading"><div><h1>Журнал событий</h1><p>События источников и результаты обработки</p></div><button id="journal-refresh" class="outline">Обновить</button></div><section class="panel"><div class="filter-grid"><label>Источник<select id="journal-source"><option value="">Все источники</option><option value="goszakup">Goszakup</option><option value="eondiris">e-ondiris</option><option value="gov">Gov.kz</option></select></label><label>Уровень<select id="journal-level"><option value="">Все события</option><option value="info">Информация</option><option value="warning">Предупреждения</option><option value="error">Ошибки</option></select></label><label>Поиск<input id="journal-query" type="search" placeholder="Текст события"></label></div></section><section class="panel table-panel"><div id="journal-events" class="table-scroll"></div><footer><span id="journal-count"></span><div><button id="journal-prev" class="outline">←</button><span id="journal-page"></span><button id="journal-next" class="outline">→</button></div></footer></section><p id="journal-error" role="status"></p>';document.body.append(journalPage);
const journalButton=document.createElement('button');journalButton.innerHTML='<svg class="icon" aria-hidden="true"><use href="icons.svg#list"></use></svg><span>Журнал</span>';collectionButton.after(journalButton);let journalNumber=1,journalBusy=false;
const previousShow=showPage;showPage=function(audiences){journalPage.hidden=true;journalButton.classList.remove('active');journalButton.removeAttribute('aria-current');previousShow(audiences);};collectionButton.addEventListener('click',()=>{journalPage.hidden=true;journalButton.classList.remove('active');journalButton.removeAttribute('aria-current');refreshProducers();});journalButton.onclick=()=>{for(const p of [mainPage,audiencePage,collectionPage])p.hidden=true;journalPage.hidden=false;for(const b of [clientsButton,audiencesButton,collectionButton]){b.classList.remove('active');b.removeAttribute('aria-current');}journalButton.classList.add('active');journalButton.setAttribute('aria-current','page');document.title='Журнал — Рассылки';loadJournal();};
async function loadJournal(){if(journalBusy)return;journalBusy=true;try{const query=new URLSearchParams({source:document.getElementById('journal-source').value,level:document.getElementById('journal-level').value,q:document.getElementById('journal-query').value,page:journalNumber});const data=await api('/api/journal?'+query);journalNumber=data.page;const container=document.getElementById('journal-events');container.replaceChildren();const table=document.createElement('table');const head=document.createElement('thead');const tr=document.createElement('tr');for(const title of ['Время','Источник','Уровень','Событие']){const th=document.createElement('th');th.textContent=title;tr.append(th);}head.append(tr);table.append(head);const body=document.createElement('tbody');for(const event of data.events){const tr=document.createElement('tr');for(const value of [new Date(event.at).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'}),{goszakup:'Goszakup',eondiris:'e-ondiris',gov:'Gov.kz',dfo:'ДФО'}[event.source]||event.source,{info:'Информация',warning:'Предупреждение',error:'Ошибка'}[event.level]||event.level,event.message]){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);}table.append(body);container.append(table);if(!data.events.length){const p=document.createElement('p');p.className='journal-empty';p.textContent='События не найдены.';container.append(p);}document.getElementById('journal-count').textContent='Событий: '+data.count;document.getElementById('journal-page').textContent=data.page+' / '+data.pages;document.getElementById('journal-prev').disabled=data.page<=1;document.getElementById('journal-next').disabled=data.page>=data.pages;document.getElementById('journal-error').textContent='';}catch(error){document.getElementById('journal-error').textContent=error.message;}finally{journalBusy=false;}}
for(const id of ['journal-source','journal-level'])document.getElementById(id).onchange=()=>{journalNumber=1;loadJournal();};let journalTimer;document.getElementById('journal-query').oninput=()=>{clearTimeout(journalTimer);journalTimer=setTimeout(()=>{journalNumber=1;loadJournal();},250);};document.getElementById('journal-refresh').onclick=loadJournal;document.getElementById('journal-prev').onclick=()=>{journalNumber--;loadJournal();};document.getElementById('journal-next').onclick=()=>{journalNumber++;loadJournal();};setInterval(()=>{if(!journalPage.hidden&&journalNumber===1)loadJournal();},5000);

